/* @lc app=leetcode id=2318 lang=kotlin */ class Solution { fun distinctSequences(n: Int): Int = if (n == 1) 6 else (2 until n).fold(Array(7) { IntArray(7) { 0 } }.apply { (1..6).forEach { i -> (1..6).forEach { j -> if (i != j && (i == 1 || j == 1 || (i % 2 != 0 || j % 2 != 0) && (i % 3 != 0 || j % 3 != 0))) this[i][j] = 1 } } }) { dp, _ -> Array(7) { IntArray(7) { 0 } }.apply { (1..6).forEach { p1 -> (1..6).forEach { p2 -> if (dp[p1][p2] > 0) (1..6).forEach { curr -> if (curr != p1 && curr != p2 && (curr == 1 || p2 == 1 || (curr % 2 != 0 || p2 % 2 != 0) && (curr % 3 != 0 || p2 % 3 != 0))) this[p2][curr] = (this[p2][curr] + dp[p1][p2]) % 1000000007 } } } } }.let { dp -> dp.sumOf { row -> row.sumOf { it.toLong() } } % 1000000007 }.toInt() }